/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Source
 *   Functions: slot, op, base, audio, candidate, project, mbid, key, lookupSlot, lookupCover, job, withJob,
 *              album
 *   Constants: now
 * Tests
 *   - an explicit choice, including No cover and a malformed stored value, wins over the shared image; no stored choice is automatic
 *   - the automatic cover is the ready candidate of the one image every confirmed file carries, first in manifest order
 *   - a confirmed file with no image, another image or unknown evidence selects nothing
 *   - a shared image without a ready image candidate selects nothing
 *   - an Album decision of reuse or skip deselects in both decision formats, while create and undecided select
 *   - a file whose saved track decision is skip never blocks the image every other file shares, whose candidate it may still hold
 *   - a publication that is not cancelled freezes the automatic choice as the cover it showed
 *   - the automatic choice follows the file set
 *   - the staging UUID reproduces every frozen embedded intent, and the cleanup UUID is derived per candidate version
 *   - the choice and the cleanup plan are total on malformed records
 *   - completion cleans every unselected automatic candidate except published, pinned or already cleaning ones, and waits for unsettled ones
 *   - before staging a replacement upload's image, the candidate its slot holds is cleanable only when nothing else needs it
 *   - the applied lookup candidate's ready cover is the automatic choice over the shared image, and explicit choices and the Album decision still win
 *   - a lookup cover that is not ready, not an image or of a candidate no longer applied falls back to the shared image
 *   - an application records the candidate whose release reports front artwork under its grant, and none without touching values or the fence
 *   - an iTunes-only candidate records its stored artwork address only when it can be fetched from the fixed artwork hosts; a MusicBrainz candidate never records one
 *   - applying the same candidate again queues a staging that failed, was skipped or ran past its grant again, under the new grant with its own intent
 *   - a lookup cover staging holds Publish only while queued or running within its grant
 *   - before completion the lookup covers no longer applied are cleaned, except an explicit choice, pinned, cleaning or unsettled ones
 *   - the embedded staging bound never counts lookup cover stagings, current or removed, while bare receipts still count
 *   - lookup covers are automatic covers, so completion cleans every one the publication did not use
 * @end-catalog */

/**
 * The automatic cover choice (the applied lookup candidate's cover, else the shared embedded image), the lookup cover job an
 * application records and the candidates completion or the lookup cover pass cleans up (adminImportCoverAutomation.ts), over
 * synthetic import records only.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ObjectId } from 'mongodb';
import { ADMIN_IMPORT_LIMITS, isLookupCoverSlot, lookupCoverSlotId, uuid } from '../../src/administration/import/adminImportContract';
import {
    automaticCoverCleanupCandidates, automaticCoverCleanupOperationId, automaticEmbeddedStagings, embeddedImportOperationId, importAlbumNotCreated, importAudioArtwork, importAutomaticCover,
    importCoverChoice, isAutomaticCoverSlot, lookupCoverCleanupCandidates, lookupCoverOperationId, lookupCoverStagingActive, noteLookupCoverApplication, replacedEmbeddedCandidateCleanable
} from '../../src/administration/import/adminImportCoverAutomation';
import type { ImportAsset, ImportLookupCover, ImportMedia, ImportPublication } from '../../src/administration/import/adminImportMediaTypes';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import type { MusicBrainzRelease } from '../../src/administration/lookup/lookupContract';
import { loadImportFixture } from '../support/adminImportFixtures';

type Source = Pick<AdminImportDocument, 'manifest' | 'media' | 'decisions'>;
const slot = (n: number) => `00000012-0000-4000-a000-${String(n).padStart(12, '0')}`;
const op = (n: number) => `00000012-0000-4000-8000-${String(n).padStart(12, '0')}`;
const [X, Y] = ['a'.repeat(64), 'b'.repeat(64)];
const now = new Date('2026-10-01T12:00:00Z');
const base = (slotId: string, operationId: string, sha256: string, contentType: string): ImportAsset => ({
    slotId, operationId, actorId: '0000000000000000000000a1', bucket: 'synthetic-private-imports', key: `imports/synthetic/${slotId}/${operationId}`, sha256, byteLength: 64, contentType,
    filename: 'synthetic', state: 'ready', versionId: 'v', etag: '"e"', updatedAt: new Date(now.getTime() - 3_600_000), leaseOwner: null, leaseUntil: null, duration: null, format: null,
    representation: null, tags: null, recovery: { operationId, expectedRevision: 1, kind: 'upload', actorId: '0000000000000000000000a1' }
});
/** File `n`'s audio upload; `artwork` undefined leaves the evidence field absent, as on uploads admitted before automatic covers. */
const audio = (n: number, artwork: string | null | undefined, extra: Partial<ImportAsset> = {}): ImportAsset =>
    ({ ...base(slot(n), op(n), String(n).repeat(64).slice(0, 64), 'audio/mpeg'), ...(artwork === undefined ? {} : { artworkSha256: artwork }), ...extra });
/** File `n`'s embedded candidate, staged under the UUID derived from that file's audio intent unless `operationId` says otherwise. */
const candidate = (n: number, sha256: string, extra: Partial<ImportAsset> = {}): ImportAsset => ({ ...base(`embedded-${slot(n)}`, embeddedImportOperationId(op(n), slot(n)), sha256, 'image/png'), ...extra });
const project = (files: number, assets: ImportAsset[], extra: Partial<Source> & { selected?: string | null; publication?: Partial<ImportPublication> } = {}): Source => {
    const { selected, publication, ...rest } = extra;
    return { manifest: { rootLabel: '', files: Array.from({ length: files }, (_, i) => ({ slotId: slot(i + 1), filename: `${i + 1}.mp3`, relativePath: `${i + 1}.mp3`, byteLength: null })) },
        media: { assets, ...(selected !== undefined ? { selectedCoverSlotId: selected } : {}), ...(publication ? { publication: publication as ImportPublication } : {}) }, decisions: [], ...rest };
};
/** Release `n`'s MBID, candidate key, lookup cover slot and staged lookup cover (admitted under its own UUID). */
const mbid = (n: number) => `0000000b-0000-4000-8000-${String(n).padStart(12, '0')}`;
const key = (n: number) => `musicbrainz:${mbid(n)}`;
const lookupSlot = (n: number) => `lookup-${key(n)}`;
const lookupCover = (n: number, extra: Partial<ImportAsset> = {}): ImportAsset => ({ ...base(lookupSlot(n), op(300 + n), n.toString(16).repeat(64), 'image/jpeg'), ...extra });
/** The lookup cover job of the applied candidate `n` (null: none applied), settled unless `extra` says otherwise. */
const job = (n: number | null, extra: Partial<ImportLookupCover> = {}): ImportLookupCover => ({ candidateKey: n === null ? null : key(n), releaseId: n === null ? null : mbid(n),
    operationId: n === null ? null : op(400 + n), state: n === null ? 'idle' : 'staged', issue: null, actorId: '0000000000000000000000a1', grantExpiresAt: new Date(now.getTime() + 3_600_000),
    due: false, leaseOwner: null, leaseUntil: null, updatedAt: now, ...extra });
const withJob = <T extends Source>(source: T, value: unknown): T => { (source.media as ImportMedia).lookupCover = value as ImportLookupCover; return source; };
const album = (action: string, entry = false) => ({ scope: 'album', slotId: null, ...(entry ? { entryKey: null, boundName: null } : {}), action, candidateId: action === 'reuse' ? '0000000000000000000000c1' : null, candidateRevision: null });

test('an explicit choice, including No cover and a malformed stored value, wins over the shared image; no stored choice is automatic', () => {
    const assets = [audio(1, X), candidate(1, X), base('cover', op(9), Y, 'image/png')];
    assert.deepEqual(importCoverChoice(project(1, assets)), { mode: 'automatic', slotId: `embedded-${slot(1)}` });
    assert.deepEqual(importCoverChoice(project(1, assets, { selected: 'cover' })), { mode: 'explicit', slotId: 'cover' });
    assert.deepEqual(importCoverChoice(project(1, assets, { selected: null })), { mode: 'explicit', slotId: null });
    const malformed = project(1, assets); (malformed.media as unknown as Record<string, unknown>).selectedCoverSlotId = 42;
    assert.deepEqual(importCoverChoice(malformed), { mode: 'explicit', slotId: null });
});

test('the automatic cover is the ready candidate of the one image every confirmed file carries, first in manifest order', () => {
    // Per-file duplicates staged before deduplication: every file has its own candidate of the same image.
    const legacy = [audio(1, undefined), candidate(1, X), audio(2, undefined), candidate(2, X), audio(3, undefined), candidate(3, X)];
    assert.equal(importAutomaticCover(project(3, legacy)), `embedded-${slot(1)}`);
    // The first file's candidate is not ready, so the next one in manifest order is chosen.
    assert.equal(importAutomaticCover(project(3, legacy.map(asset => asset.slotId === `embedded-${slot(1)}` ? { ...asset, state: 'deleted' as const } : asset))), `embedded-${slot(2)}`);
    // Audio that is pending, unknown or being removed is no confirmed file; one recorded image deduplicated to the first candidate.
    const recorded = [audio(1, X), candidate(1, X), audio(2, X), audio(3, Y, { state: 'pending' }), audio(4, null, { state: 'unknown' }), audio(5, Y, { state: 'deleting' })];
    assert.equal(importAutomaticCover(project(5, recorded)), `embedded-${slot(1)}`);
    assert.equal(importAutomaticCover(project(5, recorded.filter(asset => asset.slotId !== slot(1)))), `embedded-${slot(1)}`);
});

test('a confirmed file with no image, another image or unknown evidence selects nothing', () => {
    const shared = [audio(1, X), candidate(1, X)];
    assert.equal(importAutomaticCover(project(2, [...shared, audio(2, null)])), null);
    assert.equal(importAutomaticCover(project(2, [...shared, audio(2, Y), candidate(2, Y)])), null);
    // An upload admitted before evidence was recorded, with no candidate of its own, or one staged under another intent.
    assert.equal(importAutomaticCover(project(2, [...shared, audio(2, undefined)])), null);
    assert.equal(importAutomaticCover(project(2, [...shared, audio(2, undefined), candidate(2, X, { operationId: op(42) })])), null);
    assert.equal(importAudioArtwork([], audio(2, undefined)), undefined);
    assert.equal(importAudioArtwork([candidate(2, X, { operationId: op(42) })], audio(2, undefined)), undefined);
    assert.equal(importAudioArtwork([candidate(2, X)], audio(2, undefined)), X);
    // A malformed recorded value is unknown, never an image.
    assert.equal(importAudioArtwork([], audio(2, 'not-a-digest')), undefined);
    assert.equal(importAutomaticCover(project(1, [audio(1, 'Z'.repeat(64)), candidate(1, X)])), null);
    // No confirmed file at all selects nothing.
    assert.equal(importAutomaticCover(project(1, [audio(1, X, { state: 'pending' }), candidate(1, X)])), null);
});

test('a shared image without a ready image candidate selects nothing', () => {
    const files = [audio(1, X), audio(2, X)];
    for (const state of ['pending', 'unknown', 'deleting', 'deleted', 'cleanupFailed', 'failed'] as const) {
        assert.equal(importAutomaticCover(project(2, [...files, candidate(1, X, { state })])), null, state);
    }
    assert.equal(importAutomaticCover(project(2, [...files, candidate(1, X, { contentType: 'audio/mpeg' })])), null);
    assert.equal(importAutomaticCover(project(2, [...files, candidate(1, Y)])), null);
    // Never staged: the bound was reached, or it was deduplicated against a candidate removed with its file.
    assert.equal(importAutomaticCover(project(2, files)), null);
    // A manual cover with the same bytes is never chosen automatically.
    assert.equal(importAutomaticCover(project(2, [...files, base('cover', op(9), X, 'image/png')])), null);
});

test('an Album decision of reuse or skip deselects in both decision formats, while create and undecided select', () => {
    const assets = [audio(1, X), candidate(1, X)];
    for (const entry of [false, true]) {
        for (const action of ['reuse', 'skip']) {
            const source = project(1, assets, { decisions: [album(action, entry)] as Source['decisions'] });
            assert.equal(importAlbumNotCreated(source.decisions), true); assert.deepEqual(importCoverChoice(source), { mode: 'automatic', slotId: null }, `${action} ${entry}`);
        }
        assert.equal(importAutomaticCover(project(1, assets, { decisions: [album('create-distinct', entry)] as Source['decisions'] })), `embedded-${slot(1)}`);
    }
    assert.equal(importAutomaticCover(project(1, assets, { decisions: [] })), `embedded-${slot(1)}`);
    // An explicit choice is kept whatever the Album decision; it is the publication that copies no cover for an append.
    assert.deepEqual(importCoverChoice(project(1, assets, { selected: `embedded-${slot(1)}`, decisions: [album('reuse')] as Source['decisions'] })), { mode: 'explicit', slotId: `embedded-${slot(1)}` });
});

test('a file whose saved track decision is skip never blocks the image every other file shares, whose candidate it may still hold', () => {
    const skip = (n: number) => ({ scope: 'track', slotId: slot(n), action: 'skip', candidateId: null, candidateRevision: null }) as Source['decisions'][number];
    const assets = [audio(1, X), candidate(1, X), audio(2, Y), candidate(2, Y), audio(3, X)];
    assert.equal(importAutomaticCover(project(3, assets)), null);
    assert.equal(importAutomaticCover(project(3, assets, { decisions: [skip(2)] })), `embedded-${slot(1)}`);
    assert.deepEqual(importCoverChoice(project(3, assets, { decisions: [{ ...skip(2), entryKey: null, boundName: null } as Source['decisions'][number]] })), { mode: 'automatic', slotId: `embedded-${slot(1)}` });
    // Identical images are staged once, so the skipped first file's candidate is the shared image's only one.
    assert.equal(importAutomaticCover(project(3, assets, { decisions: [skip(1), skip(2)] })), `embedded-${slot(1)}`);
    // Every file skipped: no track carries an image.
    assert.equal(importAutomaticCover(project(3, assets, { decisions: [skip(1), skip(2), skip(3)] })), null);
});

test('a publication that is not cancelled freezes the automatic choice as the cover it showed', () => {
    const assets = [audio(1, undefined), candidate(1, X), audio(2, undefined), candidate(2, X), audio(3, undefined), candidate(3, X)];
    assert.deepEqual(importCoverChoice(project(3, assets)), { mode: 'automatic', slotId: `embedded-${slot(1)}` });
    for (const state of ['preparing', 'needsAttention', 'complete'] as const) {
        assert.deepEqual(importCoverChoice(project(3, assets, { publication: { state, cover: null } })), { mode: 'automatic', slotId: null }, state);
        assert.deepEqual(importCoverChoice(project(3, assets, { publication: { state, cover: { slotId: `embedded-${slot(2)}` } as ImportPublication['cover'] } })),
            { mode: 'automatic', slotId: `embedded-${slot(2)}` }, state);
    }
    // A cancelled publication froze nothing that stays; an explicit choice is never replaced by the frozen cover.
    assert.deepEqual(importCoverChoice(project(3, assets, { publication: { state: 'cancelled', cover: null } })), { mode: 'automatic', slotId: `embedded-${slot(1)}` });
    assert.deepEqual(importCoverChoice(project(3, assets, { selected: `embedded-${slot(3)}`, publication: { state: 'complete', cover: null } })), { mode: 'explicit', slotId: `embedded-${slot(3)}` });
    // A legacy import completed with no stored choice and no cover: every per-file duplicate is cleaned, the first included.
    assert.deepEqual(automaticCoverCleanupCandidates(project(3, assets, { publication: { state: 'complete', cover: null } }), now).reserve.map(asset => asset.slotId),
        [1, 2, 3].map(n => `embedded-${slot(n)}`));
});

test('the automatic choice follows the file set', () => {
    const shared = [audio(1, X), candidate(1, X), audio(2, X)];
    assert.equal(importAutomaticCover(project(3, shared)), `embedded-${slot(1)}`);
    const other = [...shared, audio(3, Y), candidate(3, Y)];
    assert.equal(importAutomaticCover(project(3, other)), null);
    // Removing the file with the other image restores the shared one.
    assert.equal(importAutomaticCover(project(3, other.map(asset => asset.slotId === slot(3) ? { ...asset, state: 'deleting' as const } : asset))), `embedded-${slot(1)}`);
    // A replacement upload of file 1 carrying the other image never keeps the old upload's candidate as its evidence.
    const replaced = [audio(1, undefined, { operationId: op(11) }), candidate(1, X), audio(2, X)];
    assert.equal(importAutomaticCover(project(2, replaced)), null);
    assert.equal(importAutomaticCover(project(2, [audio(1, Y, { operationId: op(11) }), candidate(1, X), audio(2, Y)])), null);
    assert.equal(importAutomaticCover(project(2, [audio(1, X, { operationId: op(11) }), candidate(1, X), audio(2, X)])), `embedded-${slot(1)}`);
});

test('the staging UUID reproduces every frozen embedded intent, and the cleanup UUID is derived per candidate version', () => {
    const doc = loadImportFixture('adminImport', 'v1-assets-reviewed.json'), assets = doc.media!.assets, embedded = assets.filter(asset => isAutomaticCoverSlot(asset.slotId));
    assert.equal(embedded.length, 2);
    for (const asset of embedded) {
        const source = assets.find(item => `embedded-${item.slotId}` === asset.slotId)!;
        assert.equal(embeddedImportOperationId(source.operationId, source.slotId), asset.operationId, asset.slotId);
    }
    const first = automaticCoverCleanupOperationId(embedded[0]);
    assert.equal(uuid(first), true); assert.equal(automaticCoverCleanupOperationId({ operationId: embedded[0].operationId, slotId: embedded[0].slotId }), first);
    assert.notEqual(automaticCoverCleanupOperationId(embedded[1]), first); assert.notEqual(automaticCoverCleanupOperationId({ ...embedded[0], operationId: op(77) }), first);
    assert.notEqual(first, embedded[0].operationId); assert.equal(new Set(embedded.map(asset => asset.operationId)).has(first), false);
    assert.equal(isAutomaticCoverSlot('cover'), false); assert.equal(isAutomaticCoverSlot(slot(1)), false); assert.equal(isAutomaticCoverSlot(42), false);
});

test('the choice and the cleanup plan are total on malformed records', () => {
    for (const source of [{ manifest: null, media: { assets: 'x' }, decisions: 'x' }, { manifest: { files: 'x' }, media: null, decisions: null },
        { manifest: { files: [null, 42, { slotId: 'x' }] }, media: { assets: [null, 42, 'x'] }, decisions: [null, 42] }, { manifest: undefined, media: [], decisions: [{ scope: 'album' }] }]) {
        assert.deepEqual(importCoverChoice(source as unknown as Source), { mode: 'automatic', slotId: null });
        assert.equal(importAutomaticCover(source as unknown as Source), null);
        assert.deepEqual(automaticCoverCleanupCandidates(source as unknown as Source, now), { reserve: [], waitUntil: null });
    }
    // A malformed frozen cover reads as none.
    assert.deepEqual(importCoverChoice(project(1, [audio(1, X), candidate(1, X)], { publication: { state: 'complete', cover: 'x' as unknown as null } })), { mode: 'automatic', slotId: null });
    assert.equal(replacedEmbeddedCandidateCleanable({ manifest: null, media: null, decisions: null } as unknown as Source, candidate(1, X), slot(1), op(11), now), true);
});

test('completion cleans every unselected automatic candidate except published, pinned or already cleaning ones, and waits for unsettled ones', () => {
    const deadline = new Date(now.getTime() + 60_000), lease = new Date(now.getTime() + 120_000), day = 24 * 3600_000;
    const assets = [
        audio(1, X), candidate(1, X), audio(2, Y), candidate(2, Y), audio(3, null),
        // Reserved: a ready candidate, a confirmed failure, and a settled unknown and pending one.
        candidate(4, 'c'.repeat(64)), candidate(5, 'd'.repeat(64), { state: 'failed', failureConfirmedAt: now }),
        candidate(6, 'e'.repeat(64), { state: 'unknown', transferDeadline: new Date(now.getTime() - 1) }), candidate(7, 'f'.repeat(64), { state: 'pending' }),
        // Kept: pinned, already cleaning, failed cleanup, removed, and a manual cover.
        candidate(8, '1'.repeat(64), { coverConsumers: ['op'] }), candidate(9, '2'.repeat(64), { state: 'deleting', recovery: { operationId: op(90), expectedRevision: 3, kind: 'cleanup', actorId: 'a' } }),
        candidate(10, '3'.repeat(64), { state: 'cleanupFailed' }), candidate(11, '4'.repeat(64), { state: 'deleted' }), base('cover', op(12), '5'.repeat(64), 'image/png'),
        // Waiting: an unknown staging whose transfer may still land, and a leased one.
        candidate(13, '6'.repeat(64), { state: 'unknown', transferDeadline: deadline }), candidate(14, '7'.repeat(64), { state: 'ready', leaseUntil: lease })
    ];
    const reserved = (source: Source) => automaticCoverCleanupCandidates(source, now).reserve.map(asset => asset.slotId);
    const expected = [4, 5, 6, 7].map(n => `embedded-${slot(n)}`);
    // Not complete: nothing.
    for (const state of ['preparing', 'needsAttention', 'cancelled'] as const) assert.deepEqual(automaticCoverCleanupCandidates(project(14, assets, { publication: { state, cover: null } }), now), { reserve: [], waitUntil: null });
    // The explicit selection and the published cover are kept.
    const explicit = automaticCoverCleanupCandidates(project(14, assets, { selected: `embedded-${slot(1)}`, publication: { state: 'complete', cover: { slotId: `embedded-${slot(2)}` } as ImportPublication['cover'] } }), now);
    // The pinned candidate is checked again a day later, after the leased one settles.
    assert.deepEqual(explicit.reserve.map(asset => asset.slotId), expected); assert.deepEqual(explicit.waitUntil, new Date(now.getTime() + day));
    // Without a published cover or explicit choice, the unselected candidates 1 and 2 go too (no image is shared).
    assert.deepEqual(reserved(project(14, assets, { publication: { state: 'complete', cover: null } })), [`embedded-${slot(1)}`, `embedded-${slot(2)}`, ...expected]);
    // An automatic choice is the cover the publication froze: kept when frozen, cleaned when derived from the files but never used.
    const sharing = [audio(1, X), candidate(1, X), audio(2, X), candidate(2, X), candidate(4, 'c'.repeat(64))];
    assert.deepEqual(reserved(project(2, sharing, { publication: { state: 'complete', cover: { slotId: `embedded-${slot(1)}` } as ImportPublication['cover'] } })), [`embedded-${slot(2)}`, `embedded-${slot(4)}`]);
    assert.deepEqual(reserved(project(2, sharing, { publication: { state: 'complete', cover: null } })), [1, 2, 4].map(n => `embedded-${slot(n)}`));
    // A pin alone still sets a time to look again, so a release that never re-arms the cleanup cannot strand the candidate.
    assert.deepEqual(automaticCoverCleanupCandidates(project(8, [candidate(8, '1'.repeat(64), { coverConsumers: ['op'] })], { publication: { state: 'complete', cover: null } }), now),
        { reserve: [], waitUntil: new Date(now.getTime() + day) });
    // Unsettled candidates wait until the latest of their leases and deadlines; a legacy one without a deadline uses its settle window.
    const legacyPending = candidate(15, '8'.repeat(64), { state: 'pending', updatedAt: now });
    assert.deepEqual(automaticCoverCleanupCandidates(project(15, [legacyPending], { publication: { state: 'complete', cover: null } }), now),
        { reserve: [], waitUntil: new Date(now.getTime() + ADMIN_IMPORT_LIMITS.uploadSettleMs) });
    assert.deepEqual(automaticCoverCleanupCandidates(project(13, [candidate(13, '6'.repeat(64), { state: 'unknown', transferDeadline: deadline })], { publication: { state: 'complete', cover: null } }), now),
        { reserve: [], waitUntil: deadline });
});

test('before staging a replacement upload\'s image, the candidate its slot holds is cleanable only when nothing else needs it', () => {
    // File 1's upload op(1) was replaced by op(11), which carries Y; its slot still holds the candidate of X staged for op(1).
    const replaced = candidate(1, X), cleanable = (assets: ImportAsset[], extra: Parameters<typeof project>[2] = {}, value = replaced, audioOperationId = op(11)) =>
        replacedEmbeddedCandidateCleanable(project(2, [audio(1, Y, { operationId: op(11) }), value, ...assets], extra), value, slot(1), audioOperationId, now);
    assert.equal(cleanable([]), true);
    assert.equal(cleanable([audio(2, Y)]), true);
    // Another file's current upload carries X (recorded, or through its own legacy candidate), so X keeps its candidate.
    assert.equal(cleanable([audio(2, X)]), false); assert.equal(cleanable([audio(2, X, { state: 'unknown' })]), false);
    assert.equal(cleanable([audio(2, undefined), candidate(2, X)]), false);
    // One being removed, or whose failure was confirmed, no longer needs it.
    assert.equal(cleanable([audio(2, X, { state: 'deleting' })]), true); assert.equal(cleanable([audio(2, X, { state: 'failed', failureConfirmedAt: now })]), true);
    // Never: the current upload's own staging, another slot's candidate, an explicit choice, a pin, or one cleaning, leased or unsettled.
    assert.equal(cleanable([], {}, replaced, op(1)), false);
    assert.equal(cleanable([], {}, candidate(2, X)), false);
    assert.equal(cleanable([], { selected: `embedded-${slot(1)}` }), false);
    assert.equal(cleanable([], {}, candidate(1, X, { coverConsumers: ['op'] })), false);
    assert.equal(cleanable([], {}, candidate(1, X, { state: 'deleting', recovery: { operationId: op(90), expectedRevision: 3, kind: 'cleanup', actorId: 'a' } })), false);
    assert.equal(cleanable([], {}, candidate(1, X, { leaseUntil: new Date(now.getTime() + 1) })), false);
    assert.equal(cleanable([], {}, candidate(1, X, { state: 'pending', updatedAt: now })), false);
    // A settled failure or unknown staging is cleaned like a ready one.
    assert.equal(cleanable([], {}, candidate(1, X, { state: 'failed', failureConfirmedAt: now })), true);
    assert.equal(cleanable([], {}, candidate(1, X, { state: 'unknown', transferDeadline: new Date(now.getTime() - 1) })), true);
});

test('the applied lookup candidate\'s ready cover is the automatic choice over the shared image, and explicit choices and the Album decision still win', () => {
    const assets = [audio(1, X), candidate(1, X), lookupCover(1)], embedded = `embedded-${slot(1)}`;
    assert.equal(importAutomaticCover(withJob(project(1, assets), job(1))), lookupSlot(1));
    assert.deepEqual(importCoverChoice(withJob(project(1, assets), job(1))), { mode: 'automatic', slotId: lookupSlot(1) });
    // It needs no embedded image at all, and wins over images that differ (which alone select nothing).
    assert.equal(importAutomaticCover(withJob(project(0, [lookupCover(1)]), job(1))), lookupSlot(1));
    const distinct = [audio(1, X), candidate(1, X), audio(2, Y), candidate(2, Y), lookupCover(1)];
    assert.equal(importAutomaticCover(withJob(project(2, distinct), job(1))), lookupSlot(1));
    assert.equal(importAutomaticCover(withJob(project(2, distinct), job(null))), null);
    // An explicit choice, No cover included, always wins.
    assert.deepEqual(importCoverChoice(withJob(project(1, [...assets, base('cover', op(9), Y, 'image/png')], { selected: 'cover' }), job(1))), { mode: 'explicit', slotId: 'cover' });
    assert.deepEqual(importCoverChoice(withJob(project(1, assets, { selected: null }), job(1))), { mode: 'explicit', slotId: null });
    // Reuse or skip deselects it in both decision formats; create (or no decision) selects it again.
    for (const entry of [false, true]) {
        for (const action of ['reuse', 'skip']) assert.deepEqual(importCoverChoice(withJob(project(1, assets, { decisions: [album(action, entry)] as Source['decisions'] }), job(1))), { mode: 'automatic', slotId: null }, `${action} ${entry}`);
        assert.equal(importAutomaticCover(withJob(project(1, assets, { decisions: [album('create-distinct', entry)] as Source['decisions'] }), job(1))), lookupSlot(1));
    }
    // Choosing none (the job's candidate is null) selects the shared embedded image; a job still queued selects nothing new.
    assert.equal(importAutomaticCover(withJob(project(1, assets), job(null))), embedded);
    assert.equal(importAutomaticCover(withJob(project(1, assets.slice(0, 2)), job(1, { state: 'queued' }))), embedded);
    // A publication that is not cancelled freezes the lookup cover it showed.
    assert.deepEqual(importCoverChoice(withJob(project(1, assets, { publication: { state: 'preparing', cover: { slotId: lookupSlot(1) } as ImportPublication['cover'] } }), job(2))),
        { mode: 'automatic', slotId: lookupSlot(1) });
});

test('a lookup cover that is not ready, not an image or of a candidate no longer applied falls back to the shared image', () => {
    const shared = [audio(1, X), candidate(1, X)], embedded = `embedded-${slot(1)}`;
    for (const state of ['pending', 'unknown', 'failed', 'deleting', 'cleanupFailed', 'deleted'] as const) {
        assert.equal(importAutomaticCover(withJob(project(1, [...shared, lookupCover(1, { state })]), job(1, { state: 'failed', issue: 'storageUnknown' }))), embedded, state);
    }
    assert.equal(importAutomaticCover(withJob(project(1, [...shared, lookupCover(1, { contentType: 'application/octet-stream' })]), job(1))), embedded);
    // Candidate 2 is applied now: candidate 1's cover is never selected, even while candidate 2's is still staging.
    assert.equal(importAutomaticCover(withJob(project(1, [...shared, lookupCover(1)]), job(2, { state: 'running' }))), embedded);
    assert.equal(importAutomaticCover(withJob(project(1, [...shared, lookupCover(1), lookupCover(2, { state: 'pending' })]), job(2))), embedded);
    // An unknown staging that reconciliation confirmed is selected while its candidate is applied, whatever the job recorded.
    assert.equal(importAutomaticCover(withJob(project(1, [...shared, lookupCover(1)]), job(1, { state: 'failed', issue: 'storageUnknown' }))), lookupSlot(1));
    // A removed record of the slot never hides the current one, and a malformed job reads as none.
    assert.equal(importAutomaticCover(withJob(project(1, [...shared, lookupCover(1, { state: 'deleted', operationId: op(1) }), lookupCover(1)]), job(1))), lookupSlot(1));
    for (const malformed of [null, 42, 'x', { candidateKey: 42 }, { candidateKey: 'musicbrainz:not-an-mbid' }, { candidateKey: mbid(1) }]) {
        assert.equal(importAutomaticCover(withJob(project(1, [...shared, lookupCover(1)]), malformed)), embedded, JSON.stringify(malformed));
    }
});

test('an application records the candidate whose release reports front artwork under its grant, and none without touching values or the fence', () => {
    const grant = { actorId: '0000000000000000000000a2', grantExpiresAt: new Date(now.getTime() + 3_600_000) }, _id = new ObjectId('0000000000000000000000d9');
    const offered = (n: number, frontArtwork: boolean | null = true) => ({ key: key(n), releaseId: mbid(n), release: { releaseId: mbid(n), frontArtwork } as MusicBrainzRelease });
    const doc = { _id, revision: 4, valueRevision: 2, updatedAt: new Date(0), lookupGate: { fence: 3, run: 1, state: 'complete', blocking: false } } as unknown as AdminImportDocument;
    // Nothing to record: no candidate, a release without (or not reporting) front artwork, or an unfetched one; no media is created.
    for (const candidate of [null, offered(1, false), offered(1, null), { key: key(1), releaseId: mbid(1), release: null }]) {
        assert.equal(noteLookupCoverApplication(doc, candidate, grant, now), false); assert.equal(doc.media, undefined);
    }
    // A malformed key is never staged.
    assert.equal(noteLookupCoverApplication(doc, { ...offered(1), key: 'musicbrainz:../x' }, grant, now), false);
    assert.equal(noteLookupCoverApplication(doc, offered(1), grant, now), true);
    const first = doc.media!.lookupCover!;
    assert.deepEqual(first, { candidateKey: key(1), releaseId: mbid(1), operationId: lookupCoverOperationId(_id.toHexString(), key(1), now), state: 'queued', issue: null,
        actorId: grant.actorId, grantExpiresAt: grant.grantExpiresAt, due: true, leaseOwner: null, leaseUntil: null, updatedAt: now });
    assert.equal(uuid(first.operationId), true); assert.deepEqual(doc.media!.assets, []);
    // Applying the same candidate again writes nothing while its staging is queued within its grant or staged.
    assert.equal(noteLookupCoverApplication(doc, offered(1), { ...grant, actorId: '0000000000000000000000a3' }, new Date(now.getTime() + 1)), false);
    first.state = 'staged';
    assert.equal(noteLookupCoverApplication(doc, offered(1), { ...grant, actorId: '0000000000000000000000a3' }, new Date(now.getTime() + 1)), false);
    assert.ok(doc.media!.lookupCover === first); assert.equal(first.state, 'staged');
    // Choosing none leaves the job idle and due, so the pass cleans what is no longer applied; none again writes nothing.
    const later = new Date(now.getTime() + 1000);
    assert.equal(noteLookupCoverApplication(doc, null, grant, later), true);
    assert.deepEqual(doc.media!.lookupCover, { candidateKey: null, releaseId: null, operationId: null, state: 'idle', issue: null, actorId: grant.actorId, grantExpiresAt: grant.grantExpiresAt,
        due: true, leaseOwner: null, leaseUntil: null, updatedAt: later });
    assert.equal(noteLookupCoverApplication(doc, offered(2, false), grant, later), false);
    // Each application gets its own staging intent, even for a candidate staged before.
    assert.equal(noteLookupCoverApplication(doc, offered(1), grant, later), true);
    assert.notEqual(doc.media!.lookupCover!.operationId, first.operationId);
    assert.equal(doc.media!.lookupCover!.operationId, lookupCoverOperationId(_id.toHexString(), key(1), later));
    assert.notEqual(lookupCoverOperationId(_id.toHexString(), key(2), later), lookupCoverOperationId(_id.toHexString(), key(1), later));
    // Neither the revision, the value counter, the update time nor the lookup fence moved.
    assert.deepEqual([doc.revision, doc.valueRevision, doc.updatedAt, doc.lookupGate], [4, 2, new Date(0), { fence: 3, run: 1, state: 'complete', blocking: false }]);
});

test('an iTunes-only candidate records its stored artwork address only when it can be fetched from the fixed artwork hosts; a MusicBrainz candidate never records one', () => {
    const grant = { actorId: '0000000000000000000000a2', grantExpiresAt: new Date(now.getTime() + 3_600_000) }, _id = new ObjectId('0000000000000000000000d7');
    const artwork = 'https://is1-ssl.mzstatic.com/image/thumb/Music126/v4/53/0f/80/530f802b/ANTCD-46555.jpg/100x100bb.jpg';
    const itunes = (artworkUrl: string | null, extra: Record<string, unknown> = {}) => ({ key: 'itunes:1689358563', releaseId: '1689358563', source: 'itunes' as const,
        release: { releaseId: '1689358563', frontArtwork: true } as MusicBrainzRelease, itunes: { storefront: 'jp' as const, artworkUrl, check: 'noRelease' as const }, ...extra });
    const doc = () => ({ _id } as unknown as AdminImportDocument);
    const queued = doc();
    assert.equal(noteLookupCoverApplication(queued, itunes(artwork), grant, now), true);
    assert.deepEqual(queued.media!.lookupCover, { candidateKey: 'itunes:1689358563', releaseId: '1689358563', artworkUrl: artwork,
        operationId: lookupCoverOperationId(_id.toHexString(), 'itunes:1689358563', now), state: 'queued', issue: null, actorId: grant.actorId, grantExpiresAt: grant.grantExpiresAt,
        due: true, leaseOwner: null, leaseUntil: null, updatedAt: now });
    // No address, one off the artwork hosts or one that is not a thumbnail address, or a key of another source: nothing to stage.
    for (const candidate of [itunes(null), itunes('https://example.test/image/thumb/x/100x100bb.jpg'), itunes('https://is1-ssl.mzstatic.com/x.jpg'),
        itunes(artwork, { key: key(1) }), itunes(artwork, { source: 'musicbrainz' })]) {
        const empty = doc();
        assert.equal(noteLookupCoverApplication(empty, candidate, grant, now), false, JSON.stringify(candidate.key));
        assert.equal(empty.media, undefined);
    }
    // A MusicBrainz candidate (one the iTunes bridge found included) keeps Cover Art Archive artwork without an address.
    const bridged = doc();
    noteLookupCoverApplication(bridged, { key: key(1), releaseId: mbid(1), source: 'musicbrainz', release: { releaseId: mbid(1), frontArtwork: true } as MusicBrainzRelease }, grant, now);
    assert.deepEqual([bridged.media!.lookupCover!.candidateKey, 'artworkUrl' in bridged.media!.lookupCover!], [key(1), false]);
});

test('applying the same candidate again queues a staging that failed, was skipped or ran past its grant again, under the new grant with its own intent', () => {
    const _id = new ObjectId('0000000000000000000000d8'), fresh = { actorId: '0000000000000000000000a3', grantExpiresAt: new Date(now.getTime() + 7_200_000) };
    const offered = { key: key(1), releaseId: mbid(1), release: { releaseId: mbid(1), frontArtwork: true } as MusicBrainzRelease };
    const reapplied = (current: Partial<ImportLookupCover>, at = now) => {
        const doc = { _id, media: { assets: [], lookupCover: job(1, { actorId: '0000000000000000000000a1', due: false, ...current }) } } as unknown as AdminImportDocument;
        return { changed: noteLookupCoverApplication(doc, offered, fresh, at), job: doc.media!.lookupCover! };
    };
    const expired = new Date(now.getTime() - 1);
    for (const [label, current] of [['failed', { state: 'failed', issue: 'unavailable' }], ['skipped', { state: 'skipped', issue: 'grantExpired', grantExpiresAt: expired }],
        ['skipped for the bound', { state: 'skipped', issue: 'bound' }], ['queued past its grant', { state: 'queued', grantExpiresAt: expired }],
        ['running past its grant', { state: 'running', grantExpiresAt: expired, leaseOwner: 'worker', leaseUntil: new Date(now.getTime() + 60_000) }]] as [string, Partial<ImportLookupCover>][]) {
        const { changed, job: queued } = reapplied(current);
        assert.equal(changed, true, label);
        assert.deepEqual(queued, { candidateKey: key(1), releaseId: mbid(1), operationId: lookupCoverOperationId(_id.toHexString(), key(1), now), state: 'queued', issue: null,
            actorId: fresh.actorId, grantExpiresAt: fresh.grantExpiresAt, due: true, leaseOwner: null, leaseUntil: null, updatedAt: now }, label);
        assert.notEqual(queued.operationId, op(401), label);
    }
    // A staging still queued or running within its grant, or staged, is left alone.
    for (const current of [{ state: 'queued' }, { state: 'running', leaseOwner: 'worker' }, { state: 'staged' }] as Partial<ImportLookupCover>[]) {
        const { changed, job: kept } = reapplied(current);
        assert.deepEqual([changed, kept.operationId, kept.actorId, kept.state], [false, op(401), '0000000000000000000000a1', current.state], String(current.state));
    }
});

test('a lookup cover staging holds Publish only while queued or running within its grant', () => {
    assert.equal(lookupCoverStagingActive(job(1, { state: 'queued' }), now), true);
    assert.equal(lookupCoverStagingActive(job(1, { state: 'running' }), now), true);
    assert.equal(lookupCoverStagingActive(job(1, { state: 'running', grantExpiresAt: now }), now), false);
    assert.equal(lookupCoverStagingActive(job(1, { state: 'queued', grantExpiresAt: new Date(now.getTime() - 1) }), now), false);
    for (const state of ['staged', 'failed', 'skipped', 'idle'] as const) assert.equal(lookupCoverStagingActive(job(1, { state }), now), false, state);
    for (const malformed of [undefined, null, 'queued', [], { state: 'queued' }, { state: 'running', grantExpiresAt: 'later' }]) assert.equal(lookupCoverStagingActive(malformed, now), false);
});

test('before completion the lookup covers no longer applied are cleaned, except an explicit choice, pinned, cleaning or unsettled ones', () => {
    const deadline = new Date(now.getTime() + 60_000), day = 24 * 3600_000;
    const assets = [audio(1, X), candidate(1, X), base('cover', op(9), Y, 'image/png'),
        lookupCover(1), lookupCover(2), lookupCover(3, { state: 'failed', failureConfirmedAt: now }), lookupCover(4, { state: 'unknown', transferDeadline: new Date(now.getTime() - 1) }),
        lookupCover(5, { coverConsumers: ['op'] }), lookupCover(6, { state: 'unknown', transferDeadline: deadline }), lookupCover(7, { state: 'cleanupFailed' }),
        lookupCover(8, { state: 'deleting', recovery: { operationId: op(98), expectedRevision: 3, kind: 'cleanup', actorId: 'a' } }), lookupCover(9, { state: 'deleted' }),
        lookupCover(10, { transferDeadline: 'soon' as unknown as Date }), lookupCover(11)];
    const planned = lookupCoverCleanupCandidates(withJob(project(1, assets, { selected: lookupSlot(11) }), job(1)), now);
    // Applied (1) and explicitly chosen (11) are kept; the embedded image and the manual cover belong to other lifecycles.
    assert.deepEqual(planned.reserve.map(asset => asset.slotId), [2, 3, 4].map(lookupSlot));
    // The earliest wait counts: the unsettled transfer is looked at once it settles, and the pin a day later on its own.
    assert.deepEqual(planned.waitUntil, deadline, 'a pin never delays a transfer that settles sooner');
    assert.deepEqual(lookupCoverCleanupCandidates(withJob(project(1, [lookupCover(6, { state: 'unknown', transferDeadline: deadline })]), job(1)), now), { reserve: [], waitUntil: deadline });
    assert.deepEqual(lookupCoverCleanupCandidates(withJob(project(1, [lookupCover(5, { coverConsumers: ['op'] })]), job(1)), now), { reserve: [], waitUntil: new Date(now.getTime() + day) });
    assert.deepEqual(lookupCoverCleanupCandidates(withJob(project(1, [lookupCover(5, { coverConsumers: ['op'] }), lookupCover(6, { state: 'unknown', transferDeadline: deadline })]), job(1)), now).waitUntil, deadline);
    // With none applied, or no job at all, the formerly applied cover goes too.
    assert.deepEqual(lookupCoverCleanupCandidates(withJob(project(1, [lookupCover(1), lookupCover(2)]), job(null)), now).reserve.map(asset => asset.slotId), [lookupSlot(1), lookupSlot(2)]);
    assert.deepEqual(lookupCoverCleanupCandidates(project(1, [lookupCover(1)]), now).reserve.map(asset => asset.slotId), [lookupSlot(1)]);
    // Moving the explicit choice away makes it cleanable; an explicit No cover keeps nothing.
    assert.deepEqual(lookupCoverCleanupCandidates(withJob(project(1, [lookupCover(11)], { selected: null }), job(1)), now).reserve.map(asset => asset.slotId), [lookupSlot(11)]);
    // Total on malformed records.
    for (const source of [{ manifest: null, media: null, decisions: null }, { media: { assets: 'x', lookupCover: 42 } }, { media: { assets: [null, 42, { slotId: lookupSlot(1) }], lookupCover: { candidateKey: 7 } } }]) {
        assert.deepEqual(lookupCoverCleanupCandidates(source as unknown as Source, now), { reserve: [], waitUntil: null });
    }
});

test('the embedded staging bound never counts lookup cover stagings, current or removed, while bare receipts still count', () => {
    const receipt = (operationId: string, kind = 'upload') => ({ operationId, kind, revision: 2, actorId: 'a', hash: 'h', at: now });
    const media = { assets: [lookupCover(1)], assetHistory: [lookupCover(2, { state: 'deleted' })] } as ImportMedia;
    assert.equal(automaticEmbeddedStagings({ media, automaticReceipts: [receipt(op(301)), receipt(op(302)), receipt(op(1)), receipt(op(2), 'cleanup')] } as unknown as AdminImportDocument), 1);
    assert.equal(automaticEmbeddedStagings({ automaticReceipts: Array.from({ length: 16 }, (_, n) => receipt(op(500 + n))) } as unknown as AdminImportDocument), 16);
    assert.equal(automaticEmbeddedStagings({ media: null, automaticReceipts: 'x' } as unknown as AdminImportDocument), 0);
    assert.equal(automaticEmbeddedStagings({ media: { assets: [null], assetHistory: 7 }, automaticReceipts: [null, 42, receipt(op(1))] } as unknown as AdminImportDocument), 1);
});

test('lookup covers are automatic covers, so completion cleans every one the publication did not use', () => {
    assert.equal(isAutomaticCoverSlot(lookupSlot(1)), true); assert.equal(isLookupCoverSlot(lookupCoverSlotId(key(1))), true);
    // An iTunes-only candidate's cover is `lookup-itunes:<collection ID>`: 1 to 12 digits without a leading zero.
    for (const value of ['lookup-itunes:1', 'lookup-itunes:123456789012']) { assert.equal(isAutomaticCoverSlot(value), true, value); assert.equal(isLookupCoverSlot(value), true, value); }
    for (const value of ['lookup-', 'lookup-x', `lookup-musicbrainz:${mbid(1).toUpperCase()}`, 'lookup-itunes:0', 'lookup-itunes:01', 'lookup-itunes:1234567890123', 'lookup-itunes:1/x', `${lookupSlot(1)}/x`, 42]) {
        assert.equal(isAutomaticCoverSlot(value), false, String(value)); assert.equal(isLookupCoverSlot(value), false, String(value));
    }
    const assets = [lookupCover(1), lookupCover(2), lookupCover(3, { state: 'deleted' }), audio(1, X), candidate(1, X)];
    const published = withJob(project(1, assets, { publication: { state: 'complete', cover: { slotId: lookupSlot(1) } as ImportPublication['cover'] } }), job(1));
    assert.deepEqual(automaticCoverCleanupCandidates(published, now).reserve.map(asset => asset.slotId), [lookupSlot(2), `embedded-${slot(1)}`]);
    // An append froze no cover: the applied candidate's cover is cleaned as well.
    const appended = withJob(project(1, assets, { publication: { state: 'complete', cover: null } }), job(1));
    assert.deepEqual(automaticCoverCleanupCandidates(appended, now).reserve.map(asset => asset.slotId), [lookupSlot(1), lookupSlot(2), `embedded-${slot(1)}`]);
});
